import { API, graphqlOperation } from "aws-amplify";
import { list_all_requested_assets } from "@/graphql/queries.js";
import DispatchAssests from "@/components/Asset/Popups/DispatchAssests.vue";
import RejectionAsset from "@/components/Asset/Popups/RejectionAsset.vue";
import SnackBar from "@/components/SnackBar.vue";
export default {
  components: {
    SnackBar,
    DispatchAssests,
    RejectionAsset
  },
  emits: ['backAction'],
  data() {
    return {
      headers: [{
        title: "Asset ",
        key: "asset_prefix",
        sortable: false
      }, {
        title: "Requested  By",
        key: "user_id_text",
        sortable: false
      }, {
        title: "Category",
        key: "category_id_text",
        sortable: false
      }, {
        title: "Subcategory",
        key: "sub_category_id_text",
        sortable: false
      }, {
        title: "Comments",
        key: "asset_description",
        sortable: false
      }, {
        title: "Location",
        key: "location_id_text",
        sortable: false
      }

      // { title: "Status", key: "asset_dispatch_status", sortable: false },
      // { title: "Location", key: "asset_prefix", sortable: false },
      // { title: "Action", key: "Action", sortable: false },
      ],
      tableData: [],
      fixed: true,
      tableLoading: false,
      componentCheck: 0,
      dispatchWorkflow: false,
      rowData: {},
      rejectWorkflow: false,
      currentPage: 1,
      itemsPerPage: 20,
      paginatedItems: [],
      windowHeight: 0
    };
  },
  created() {
    this.fetch_requested_asset();
  },
  mounted() {
    this.updateWindowHeight();
    window.addEventListener('resize', this.updateWindowHeight);
  },
  beforeDestroy() {
    window.removeEventListener('resize', this.updateWindowHeight);
  },
  computed: {
    totalTaskCount() {
      return this.masterData ? this.masterData.length : 0;
    },
    totalCount() {
      return this.tableData.length;
    },
    pageCount() {
      return Math.ceil(this.tableData.length / this.itemsPerPage);
    },
    visiblePages() {
      const totalPages = this.pageCount;
      const current = this.currentPage;
      const delta = 2;
      let start = Math.max(1, current - delta);
      let end = Math.min(totalPages, current + delta);
      if (end - start < 4) {
        if (start === 1) {
          end = Math.min(totalPages, start + 4);
        } else {
          start = Math.max(1, end - 4);
        }
      }
      const pages = [];
      for (let i = start; i <= end; i++) {
        pages.push(i);
      }
      return pages;
    },
    // Filter out items with missing critical properties
    validTableData() {
      return this.tableData.filter(item => {
        return item && typeof item === 'object';
      });
    }
  },
  watch: {
    currentPage() {
      this.updatePageItems();
    }
  },
  methods: {
    async updatePageItems() {
      const start = (this.currentPage - 1) * this.itemsPerPage;
      const end = start + this.itemsPerPage;
      // Check if we need more data from API
      if (end > this.validTableData.length && this.next_token) {
        await this.fetch_requested_asset(true);
      }
      this.paginatedItems = this.validTableData.slice(start, end);
    },
    success_msg(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.rejectDialog = false;
      this.rejectWorkflow = false;
      this.fetch_requested_asset();
    },
    error_msg(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    },
    refresh_icon() {
      this.fetch_requested_asset();
    },
    async fetch_requested_asset() {
      this.tableLoading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(list_all_requested_assets, {
          input: {
            action_type: "DISPATCHED",
            limit: 200,
            nextToken: null
          }
        }));
        this.tableData = [];
        var response = JSON.parse(result.data.list_all_requested_assets);
        this.tableLoading = false;
        if (response.Status == "SUCCESS") {
          this.tableLoading = false;
          // console.log(response.data);
          response.data.forEach(element => {
            const newItem = {
              ...element.workflow_payload,
              // Spread the existing properties
              responeObj: element,
              asset_dispatch_status: element.asset_dispatch_status,
              asset_dispatch_comments: element.asset_dispatch_comments,
              // Add your new key-value pair here
              // Ensure asset_description has a fallback value
              asset_description: element.workflow_payload?.asset_description || element.asset_description || "No description available"
            };
            this.tableData.push(newItem);
            this.updatePageItems();
          });

          // Clean up any invalid data after processing
          this.cleanupData();
        } else {
          this.tableLoading = false;
          this.tableData = [];
        }
      } catch (error) {
        this.tableLoading = false;
        // console.log(error);
        this.tableData = [];
      }
    },
    disptach_workflow(item) {
      if (!item) {
        console.warn('Dispatch workflow called with undefined item');
        return;
      }
      this.componentCheck = 1;
      this.rowData = item;
      this.dispatchWorkflow = true;
    },
    reject_action(item) {
      if (!item) {
        console.warn('Reject action called with undefined item');
        return;
      }
      this.componentCheck = 2;
      this.rowData = item;
      this.rejectDialog = true;
    },
    updateWindowHeight() {
      this.windowHeight = window.innerHeight - 320; // Adjust height as needed
    },
    // Clean up data to remove invalid items
    cleanupData() {
      this.tableData = this.tableData.filter(item => {
        return item && typeof item === 'object' && item.asset_description !== undefined;
      });
      this.updatePageItems();
    }
  }
};
